-- 03 · Configuración de Condominio (ramo 16) y Hogar (ramo 38): copia de QA (.80) a PROD.
-- Inserta las filas que faltan y actualiza las que difieren (sin contar columnas de auditoría). No borra nada de PROD.
-- Respaldo: antes de tocar nada copia las filas actuales de PROD a tablas bk_pase_condo_20261117_<tabla>.
-- MODO PRUEBA por defecto (@aplicar = 0): muestra cuántas filas cambiaría y hace ROLLBACK. Para aplicar, poner @aplicar = 1.
-- Requiere 01_tablas_nexus.sql aplicado.
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @aplicar BIT = 0;
DECLARE @ins INT, @upd INT;
IF OBJECT_ID('tempdb..#resumen') IS NOT NULL DROP TABLE #resumen;
CREATE TABLE #resumen (tabla SYSNAME, filas_qa INT, insertadas INT, actualizadas INT);
BEGIN TRAN;

-- ===== maramos (2 filas en QA) =====
IF OBJECT_ID('dbo.bk_pase_condo_20261117_maramos', 'U') IS NULL SELECT t.* INTO dbo.[bk_pase_condo_20261117_maramos] FROM dbo.[maramos] t WHERE t.cramo IN (16, 38);
SELECT TOP 0 [cramo], [u_version], [xdescripcion_l], [xdescripcion_c], [xabreviatura], [pdevcp_1], [pdevcp_2], [pdevcp_3], [pdevcp_4], [pdevcp_5], [pdevcp_6], [pdevcp_7], [pdevcp_8], [pdevcp_9], [pdevcp_10], [pdevcp_11], [pdevcp_12], [pemicp_1], [pemicp_2], [pemicp_3], [pemicp_4], [pemicp_5], [pemicp_6], [pemicp_7], [pemicp_8], [pemicp_9], [pemicp_10], [pemicp_11], [pemicp_12], [ctiporamo], [cramoint], [iplanpers], [iestado], [cprog], [ifuente], [bok], [cerror], [fingreso], [cusuario], [ccategoria], [cusuarioauto], [ccategoriaauto], [fultmod], [cusuariomod], [ccategoriamod] INTO #s1 FROM dbo.[maramos];
UPDATE t SET [xdescripcion_l] = s.[xdescripcion_l], [xdescripcion_c] = s.[xdescripcion_c], [xabreviatura] = s.[xabreviatura], [pdevcp_1] = s.[pdevcp_1], [pdevcp_2] = s.[pdevcp_2], [pdevcp_3] = s.[pdevcp_3], [pdevcp_4] = s.[pdevcp_4], [pdevcp_5] = s.[pdevcp_5], [pdevcp_6] = s.[pdevcp_6], [pdevcp_7] = s.[pdevcp_7], [pdevcp_8] = s.[pdevcp_8], [pdevcp_9] = s.[pdevcp_9], [pdevcp_10] = s.[pdevcp_10], [pdevcp_11] = s.[pdevcp_11], [pdevcp_12] = s.[pdevcp_12], [pemicp_1] = s.[pemicp_1], [pemicp_2] = s.[pemicp_2], [pemicp_3] = s.[pemicp_3], [pemicp_4] = s.[pemicp_4], [pemicp_5] = s.[pemicp_5], [pemicp_6] = s.[pemicp_6], [pemicp_7] = s.[pemicp_7], [pemicp_8] = s.[pemicp_8], [pemicp_9] = s.[pemicp_9], [pemicp_10] = s.[pemicp_10], [pemicp_11] = s.[pemicp_11], [pemicp_12] = s.[pemicp_12], [ctiporamo] = s.[ctiporamo], [cramoint] = s.[cramoint], [iplanpers] = s.[iplanpers], [iestado] = s.[iestado], [fultmod] = GETDATE()
FROM dbo.[maramos] t JOIN #s1 s ON t.[cramo] = s.[cramo]
WHERE EXISTS (SELECT s.[xdescripcion_l], s.[xdescripcion_c], s.[xabreviatura], s.[pdevcp_1], s.[pdevcp_2], s.[pdevcp_3], s.[pdevcp_4], s.[pdevcp_5], s.[pdevcp_6], s.[pdevcp_7], s.[pdevcp_8], s.[pdevcp_9], s.[pdevcp_10], s.[pdevcp_11], s.[pdevcp_12], s.[pemicp_1], s.[pemicp_2], s.[pemicp_3], s.[pemicp_4], s.[pemicp_5], s.[pemicp_6], s.[pemicp_7], s.[pemicp_8], s.[pemicp_9], s.[pemicp_10], s.[pemicp_11], s.[pemicp_12], s.[ctiporamo], s.[cramoint], s.[iplanpers], s.[iestado] EXCEPT SELECT t.[xdescripcion_l], t.[xdescripcion_c], t.[xabreviatura], t.[pdevcp_1], t.[pdevcp_2], t.[pdevcp_3], t.[pdevcp_4], t.[pdevcp_5], t.[pdevcp_6], t.[pdevcp_7], t.[pdevcp_8], t.[pdevcp_9], t.[pdevcp_10], t.[pdevcp_11], t.[pdevcp_12], t.[pemicp_1], t.[pemicp_2], t.[pemicp_3], t.[pemicp_4], t.[pemicp_5], t.[pemicp_6], t.[pemicp_7], t.[pemicp_8], t.[pemicp_9], t.[pemicp_10], t.[pemicp_11], t.[pemicp_12], t.[ctiporamo], t.[cramoint], t.[iplanpers], t.[iestado]);
SET @upd = @@ROWCOUNT;
SELECT s.[cramo], s.[u_version], s.[xdescripcion_l], s.[xdescripcion_c], s.[xabreviatura], s.[pdevcp_1], s.[pdevcp_2], s.[pdevcp_3], s.[pdevcp_4], s.[pdevcp_5], s.[pdevcp_6], s.[pdevcp_7], s.[pdevcp_8], s.[pdevcp_9], s.[pdevcp_10], s.[pdevcp_11], s.[pdevcp_12], s.[pemicp_1], s.[pemicp_2], s.[pemicp_3], s.[pemicp_4], s.[pemicp_5], s.[pemicp_6], s.[pemicp_7], s.[pemicp_8], s.[pemicp_9], s.[pemicp_10], s.[pemicp_11], s.[pemicp_12], s.[ctiporamo], s.[cramoint], s.[iplanpers], s.[iestado], s.[cprog], s.[ifuente], s.[bok], s.[cerror], s.[fingreso], s.[cusuario], s.[ccategoria], s.[cusuarioauto], s.[ccategoriaauto], s.[fultmod], s.[cusuariomod], s.[ccategoriamod] FROM #s1 s WHERE NOT EXISTS (SELECT 1 FROM dbo.[maramos] t WHERE t.[cramo] = s.[cramo]);
