-- ===== raramos (2 filas en QA) =====
IF OBJECT_ID('dbo.bk_pase_condo_20261117_raramos', 'U') IS NULL SELECT t.* INTO dbo.[bk_pase_condo_20261117_raramos] FROM dbo.[raramos] t WHERE t.cramo IN (16, 38);
SELECT TOP 0 [cramo], [u_version], [ifpagrupado], [isumarecibo], [ctiporamo], [fingreso], [ibloqueado], [icerrado], [cusuario], [ccategoria], [cusuarioauto], [ccategoriaauto], [fultmod], [cusuariomod], [ccategoriamod] INTO #s2 FROM dbo.[raramos];
