FROM dbo.[raramos] t JOIN #s2 s ON t.[cramo] = s.[cramo]
WHERE EXISTS (SELECT s.[ifpagrupado], s.[isumarecibo], s.[ctiporamo], s.[ibloqueado], s.[icerrado] EXCEPT SELECT t.[ifpagrupado], t.[isumarecibo], t.[ctiporamo], t.[ibloqueado], t.[icerrado]);
SET @upd = @@ROWCOUNT;
SELECT s.[cramo], s.[u_version], s.[ifpagrupado], s.[isumarecibo], s.[ctiporamo], s.[fingreso], s.[ibloqueado], s.[icerrado], s.[cusuario], s.[ccategoria], s.[cusuarioauto], s.[ccategoriaauto], s.[fultmod], s.[cusuariomod], s.[ccategoriamod] FROM #s2 s WHERE NOT EXISTS (SELECT 1 FROM dbo.[raramos] t WHERE t.[cramo] = s.[cramo]);
SET @ins = @@ROWCOUNT;

